// DirroDancer runtime: materials, outfits, Mixamo clip decks, breathing, blink, arm anti-clip.
// Engine-agnostic: pass in your THREE namespace (r160+). Used by the rig-check page and by DirroDJ (Cly3DJ).
//
//   const d = createDancer(THREE, gltf, { mixamoClips: [clipA, clipB] });
//   scene.add(d.root);  d.setOutfit('Black');  d.play('SambaDance', 0.8);
//   per frame: d.update(dt);

// Tiled skin micro-normal (Unity_Normal_DetailB from the Cyber Tower asset), 256 px WebP
const SKIN_DETAIL_B64 = '';

export function createDancer(THREE, gltf, opts = {}) {
  const root = gltf.scene;
  const o = Object.assign({
    breathPower: 40,        // CTBreath.Power1 (Unity blend-shape weight, 0..100)
    breathFrequency: 0.7,   // CTBreath.Frequency (cos(t*PI*f) -> one breath every 1/(f/2) s = 2.86 s)
    breathMorph: 'breath1', // CTBreath.MorphName1
    blink: true,
    antiClip: true,
    // skin scattering (real-time approximation of HDRP's diffusion profile)
    sssColor: [0.92, 0.72, 0.62], // colour light picks up under the skin
    sssWrap: 0.1,                 // how far light bleeds past the shadow terminator
    sssTransmit: 0.0,                // back-light glow off: the asset's translucency map is too coarse and draws hard patches
    pupil: 0.5,                    // EyeSize morph (iris/lens size); the pupil itself is painted dilated in the texture
    lookAt: null,                  // optional Object3D the eyes follow; null (default) = fixed gaze
    eyePitch: -2,                  // fixed gaze: degrees down (negative) from straight ahead
    lookMax: 0.42,                 // max eye turn in radians (~24 deg)                   // EyeSize morph: Unity drives it to 1 in dim light (dilated, warm look)
    lidRest: 0.24,                 // relaxed, heavy-lidded eyes (0 = wide open)
    hairSway: 1,                   // spring sway of the bob              // back-light through ears / fingers / nostrils (rim-light glow)
    poreStrength: 0.35,            // tiled micro-normal on skin only
    poreScale: 28,
    poreNear: 0.9, poreFar: 2.2,   // #562 the pore normal fades between these camera distances (m); the scattering no longer fades
  }, opts);
  const skinUniforms = {
    uSSSColor: { value: new THREE.Color(...o.sssColor) }, uWrap: { value: o.sssWrap }, uTransmit: { value: o.sssTransmit },
    uSkinOn: { value: 1 }, uDetailStrength: { value: o.poreStrength }, uDetailScale: { value: o.poreScale },
    uDetailN: { value: null }, uPoreNear: { value: o.poreNear }, uPoreFar: { value: o.poreFar },
  };
  if (SKIN_DETAIL_B64) {
    const img = new Image(); img.src = 'data:image/webp;base64,' + SKIN_DETAIL_B64;
    const tx = new THREE.Texture(img); tx.wrapS = tx.wrapT = THREE.RepeatWrapping; tx.colorSpace = THREE.NoColorSpace;
    img.onload = () => { tx.needsUpdate = true; }; skinUniforms.uDetailN.value = tx;
  }
  function skinShader(mat) {
    const sssMap = mat.thicknessMap; // R = latex mask (clearcoat), G = translucency, B = skin mask
    mat.thicknessMap = null; mat.thickness = 0; mat.transmission = 0;
    mat.sheen = 0; mat.specularIntensity = 1; mat.ior = 1.4; mat.metalness = 0;
    mat.userData.sss = sssMap;
    mat.onBeforeCompile = (sh) => {
      Object.assign(sh.uniforms, skinUniforms, { uSSSMap: { value: sssMap } });
      sh.fragmentShader = sh.fragmentShader
        .replace('#include <common>', `#include <common>
uniform sampler2D uSSSMap; uniform sampler2D uDetailN; uniform vec3 uSSSColor;
uniform float uWrap, uTransmit, uSkinOn, uDetailStrength, uDetailScale, uPoreNear, uPoreFar;
float gSkin = 0.0; float gThin = 0.0; float gNear = 1.0; vec3 gSmoothN = vec3(0.0, 0.0, 1.0);`)
        .replace('#include <normal_fragment_maps>', `
#ifdef USE_NORMALMAP
  { vec3 sssT = texture2D( uSSSMap, vNormalMapUv ).rgb; gNear = 1.0 - smoothstep( uPoreNear, uPoreFar, length( vViewPosition ) ); gSkin = sssT.b * uSkinOn; gThin = sssT.g; }   // #562 gSkin was * gNear: past 2.2 m the skin lost its scattering and looked like plastic
  gSmoothN = normal;
#endif
#include <normal_fragment_maps>`)
        .replace('mapN.xy *= normalScale;', `mapN.xy *= normalScale;
  { vec3 dN = texture2D( uDetailN, vNormalMapUv * uDetailScale ).xyz * 2.0 - 1.0;
    mapN = normalize( vec3( mapN.xy + dN.xy * uDetailStrength * gSkin * gNear, mapN.z ) ); }`)
        .replace('#include <lights_physical_pars_fragment>', `#include <lights_physical_pars_fragment>
void RE_Direct_Skin( const in IncidentLight directLight, const in vec3 geometryPosition, const in vec3 geometryNormal, const in vec3 geometryViewDir, const in vec3 geometryClearcoatNormal, const in PhysicalMaterial material, inout ReflectedLight reflectedLight ) {
  RE_Direct_Physical( directLight, geometryPosition, geometryNormal, geometryViewDir, geometryClearcoatNormal, material, reflectedLight );
  if ( gSkin > 0.001 ) {
    vec3 sN = normalize( mix( gSmoothN, geometryNormal, 0.25 ) );   // scattering blurs fine normal detail
    float ndl = dot( sN, directLight.direction );
    float wrapped = clamp( ( ndl + uWrap ) / ( 1.0 + uWrap ), 0.0, 1.0 );
    float bleed = max( wrapped - clamp( ndl, 0.0, 1.0 ), 0.0 );
    reflectedLight.directDiffuse += bleed * directLight.color * uSSSColor * BRDF_Lambert( material.diffuseColor ) * gSkin;
    if ( uTransmit > 0.0 ) {
      vec3 H = normalize( directLight.direction + sN * 0.35 );
      float back = pow( clamp( dot( geometryViewDir, -H ), 0.0, 1.0 ), 4.0 );
      reflectedLight.directDiffuse += back * gThin * uTransmit * directLight.color * uSSSColor * material.diffuseColor * gSkin;
    }
  }
}
#undef RE_Direct
#define RE_Direct RE_Direct_Skin`);
    };
    mat.customProgramCacheKey = () => 'dirro-skin-v4';
    mat.needsUpdate = true;
    return mat;
  }

  // ---------- hair sway (the bob is skinned to the head only, so it gets a spring offset in the vertex shader) ----------
  const hairU = { uHairSway: { value: new THREE.Vector3() }, uHairTop: { value: 0.85 }, uHairBot: { value: -0.85 } };
  function hairShader(mat) {
    mat.onBeforeCompile = (sh) => {
      Object.assign(sh.uniforms, hairU);
      sh.vertexShader = sh.vertexShader
        .replace('#include <common>', '#include <common>\nuniform vec3 uHairSway; uniform float uHairTop, uHairBot;')
        .replace('#include <project_vertex>', `#include <project_vertex>
  { float hw = clamp( ( uHairTop - position.y ) / max( uHairTop - uHairBot, 1e-4 ), 0.0, 1.0 ); hw = hw * hw;
    mvPosition.xyz += ( viewMatrix * vec4( uHairSway * hw, 0.0 ) ).xyz; gl_Position = projectionMatrix * mvPosition; }`);
    };
    mat.customProgramCacheKey = () => 'dirro-hair-v1'; mat.needsUpdate = true;
  }

  // ---------- materials ----------
  const meshes = [];
  root.traverse((n) => { if (n.isMesh) { meshes.push(n); n.castShadow = true; n.frustumCulled = false; } });

  const upgraded = new Map();
  function upgrade(mat) {
    if (!mat || upgraded.has(mat)) return upgraded.get(mat) || mat;
    let out = mat;
    const name = mat.name || '';
    if (/^Body_/.test(name) && mat.isMeshPhysicalMaterial) {
      out = skinShader(mat);
    } else if (name === 'Hair') {
      mat.alphaToCoverage = true;                          // soft strand edges with MSAA / XR
      mat.side = THREE.DoubleSide; mat.metalness = 0; mat.roughness = 0.42;
      if ('anisotropy' in mat) { /* standard mat has no anisotropy; swap to physical */ }
      out = new THREE.MeshPhysicalMaterial();
      THREE.MeshStandardMaterial.prototype.copy.call(out, mat);
      out.name = name; out.alphaToCoverage = true; out.transparent = false; out.alphaTest = 0.5;
      out.anisotropy = 0.35; out.anisotropyRotation = Math.PI / 2; out.roughness = 0.55;
      out.specularIntensity = 0.35; out.envMapIntensity = 0.6;
      hairShader(out);
    } else if (name === 'HairTop') {
      mat.depthWrite = false; mat.side = THREE.DoubleSide; mat.roughness = 0.6; mat.envMapIntensity = 0.5; mat.opacity = 0.35; mat.transparent = true;
      hairShader(mat);
    } else if (name === 'Cornea') {
      mat.depthWrite = false;
    } else if (name === 'Brow' || name === 'Lash') {
      // fine strand cards: no shine, so rim lights don't draw a grey-white fringe; brows a little denser and darker
      // unlit: the strands are too thin to need shading, and lit they pick up the rim lights as a frosty fringe
      out = new THREE.MeshBasicMaterial({ name, side: THREE.DoubleSide,
        color: name === 'Brow' ? new THREE.Color(0.03, 0.018, 0.012) : new THREE.Color(0.008, 0.006, 0.005),
        transparent: name === 'Brow', opacity: name === 'Brow' ? 0.55 : 1, depthWrite: name !== 'Brow' });
    } else if (name === 'Eye') {
      mat.color.setScalar(0.82); mat.roughness = 0.4; // softer, less staring whites
    }
    upgraded.set(mat, out);
    return out;
  }
  { const h = meshes.find((m) => /^Hair/.test(m.material?.name || ''));
    if (h) { h.geometry.computeBoundingBox(); hairU.uHairTop.value = h.geometry.boundingBox.max.y; hairU.uHairBot.value = h.geometry.boundingBox.min.y; } }
  for (const m of meshes) {
    m.material = upgrade(m.material);
    if (m.material.name === 'HairTop') m.renderOrder = 2;
    if (m.material.name === 'Cornea') m.renderOrder = 3;
  }
  // Eyes: the asset stacks three clear shells (cornea, cornea-solid, lens) over the iris; together they turn it milky.
  // Hide all three and put the wet highlight on the eyeball as a clearcoat instead.
  root.traverse((g) => {
    if (!/^Eye(Left|Right)/.test(g.name) || g.isMesh) return;
    const shells = g.children.filter((c) => c.isMesh && c.material?.name === 'Cornea')
      .sort((x, y) => y.geometry.attributes.position.count - x.geometry.attributes.position.count);
    shells.forEach((c) => { c.visible = false; });
    for (const c of g.children) if (c.isMesh && c.material?.name === 'Eye' && !c.material.isMeshPhysicalMaterial) {
      const m = new THREE.MeshPhysicalMaterial(); THREE.MeshStandardMaterial.prototype.copy.call(m, c.material);
      m.name = 'Eye'; m.clearcoat = 1; m.clearcoatRoughness = 0.04; m.roughness = 0.45; c.material = m;   // wet cornea highlight on the eyeball itself
    }
  });
  // Rope halter: started as body faces, so give it its own material copy with a depth bias that keeps it over the skin.
  function biasRope() {
    root.traverse((n) => {
      if (!n.isMesh) return; let p = n; while (p && p.name !== 'Rope' && p !== root) p = p.parent;
      if (!p || p === root) return;
      if (!n.material.userData.ropeBias) {
        const m = n.material.clone(); m.onBeforeCompile = n.material.onBeforeCompile; m.customProgramCacheKey = n.material.customProgramCacheKey;
        m.polygonOffset = true; m.polygonOffsetFactor = -2; m.polygonOffsetUnits = -8; m.userData.ropeBias = true; n.material = m;
      }
    });
  }
  biasRope();
  // Two-pass hair: cut-out strands write depth, then a blended pass draws the soft strand tips the cut-out dropped.
  for (const m of meshes.slice()) {
    if (m.material.name !== 'Hair' || !m.isSkinnedMesh) continue;
    m.material.alphaTest = 0.5;
    const soft = m.clone(); const sm = m.material.clone();
    sm.alphaTest = 0.04; sm.alphaToCoverage = false; sm.transparent = true; sm.depthWrite = false; sm.name = 'HairSoft';
    hairShader(sm); soft.material = sm; soft.renderOrder = 1; soft.castShadow = false;
    soft.bind(m.skeleton, m.bindMatrix); m.parent.add(soft);
  }

  // ---------- outfits (KHR_materials_variants) ----------
  const parser = gltf.parser;
  const vext = gltf.userData?.gltfExtensions?.KHR_materials_variants;
  const outfits = (vext?.variants || []).map((v) => v.name);
  async function setOutfit(name) {
    const idx = outfits.indexOf(name); if (idx < 0) return;
    const jobs = [];
    for (const m of meshes) {
      const ext = m.userData.gltfExtensions?.KHR_materials_variants; if (!ext) continue;
      const map = ext.mappings.find((x) => x.variants.includes(idx)); if (!map) continue;
      jobs.push(parser.getDependency('material', map.material).then((mat) => {
        m.material = mat; parser.assignFinalMaterial(m); m.material = upgrade(m.material);
      }));
    }
    await Promise.all(jobs); biasRope();
  }

  // ---------- bones ----------
  const bone = {};
  root.traverse((n) => { if (n.isBone) bone[n.name.replace(/^mixamorig:?/, '')] = n; });

  // ---------- Mixamo clips -> decks ----------
  const names = new Set(); root.traverse((n) => names.add(n.name));
  function cleanClip(clip) {
    // keep bone rotations + hip translation only (Mixamo per-bone positions would reshape her)
    const tracks = clip.tracks.filter((t) => {
      const i = t.name.lastIndexOf('.'); const node = t.name.slice(0, i), prop = t.name.slice(i + 1);
      return names.has(node) && (prop === 'quaternion' || (prop === 'position' && /Hips$/.test(node)));
    });
    return new THREE.AnimationClip(clip.name, clip.duration, tracks);
  }
  const mixer = new THREE.AnimationMixer(root);
  const actions = new Map();
  function addClip(clip, name = clip.name) {
    const c = cleanClip(clip); c.name = name;
    const a = mixer.clipAction(c); a.enabled = true; a.setEffectiveWeight(0); a.play();
    actions.set(name, a); return a;
  }
  (opts.mixamoClips || []).forEach((c) => addClip(c));
  let current = null;
  function play(name, fade = 0.6, { sync = false } = {}) {
    const next = actions.get(name); if (!next || next === current) return;
    next.enabled = true;
    if (current) {
      if (sync) next.syncWith(current);
      next.setEffectiveWeight(1); current.crossFadeTo(next, fade, false);
    } else { next.setEffectiveWeight(1); next.fadeIn(fade); }
    current = next;
  }
  function setWeights(map) { // manual VJ mixing: { SambaDance: 0.7, HipHop: 0.3 }
    for (const [k, a] of actions) a.setEffectiveWeight(map[k] ?? 0);
  }

  // ---------- breathing (port of ILranch CTBreath) ----------
  const breathTargets = meshes.filter((m) => m.morphTargetDictionary && o.breathMorph in m.morphTargetDictionary);
  const blinkTargets = meshes.filter((m) => m.morphTargetDictionary && 'EyeLClose' in m.morphTargetDictionary);
  const pupilTargets = meshes.filter((m) => m.morphTargetDictionary && 'EyeSize' in m.morphTargetDictionary);
  let t = 0, nextBlink = 1.5, blinkT = -1; const hs = { prev: null, pos: new THREE.Vector3(), vel: new THREE.Vector3() };
  const state = { breathScale: 1 }; // raise during heavy dancing, e.g. 1.6

  // ---------- eye look-at: turn the eye bones toward the camera, clamped, smoothed ----------
  const eyeRig = [];
  (function setupEyes() {
    const foot = bone.LeftFoot, toe = bone.LeftToeBase; if (!foot || !toe) return;
    root.updateMatrixWorld(true);
    const fwd = toe.getWorldPosition(new THREE.Vector3()).sub(foot.getWorldPosition(new THREE.Vector3())); fwd.y = 0; fwd.normalize();
    for (const n of ['LeftEye', 'RightEye']) {
      const b = bone[n]; if (!b) continue;
      const q = b.getWorldQuaternion(new THREE.Quaternion()).invert();
      eyeRig.push({ b, local: fwd.clone().applyQuaternion(q), corr: new THREE.Quaternion(), rest: b.quaternion.clone() });
    }
  })();
  function solveEyes(dt) {
    const tgt = o.lookAt; const wq = new THREE.Quaternion(), pq = new THREE.Quaternion(), want = new THREE.Quaternion();
    for (const e of eyeRig) {
      want.identity();
      if (!tgt && o.eyePitch) {
        e.b.getWorldQuaternion(wq);
        const cur = e.local.clone().applyQuaternion(wq);
        const axis = new THREE.Vector3().crossVectors(cur, new THREE.Vector3(0, -1, 0));
        if (axis.lengthSq() > 1e-8) want.setFromAxisAngle(axis.normalize(), -o.eyePitch * Math.PI / 180);
      }
      if (tgt) {
        e.b.getWorldQuaternion(wq);
        const cur = e.local.clone().applyQuaternion(wq);
        const to = tgt.getWorldPosition(new THREE.Vector3()).sub(e.b.getWorldPosition(new THREE.Vector3())).normalize();
        want.setFromUnitVectors(cur, to);
        const ang = 2 * Math.acos(Math.min(1, Math.abs(want.w)));
        if (ang > o.lookMax) want.slerp(new THREE.Quaternion(), ang > 1.4 ? 1 : 1 - o.lookMax / ang); // looking away past ~80 deg: rest
      }
      e.corr.slerp(want, 1 - Math.exp(-dt * 14));
      e.b.parent.getWorldQuaternion(pq); e.b.getWorldQuaternion(wq); wq.premultiply(e.corr);
      e.b.quaternion.copy(pq.invert().multiply(wq)); e.b.updateMatrixWorld(true);
    }
  }

  // ---------- anti-clip: keep hands / forearms out of torso and shoulders ----------
  const V = THREE.Vector3;
  const tmp = { a: new V(), b: new V(), p: new V(), c: new V(), s: new V(), axis: new V(), q: new THREE.Quaternion(), wq: new THREE.Quaternion(), pq: new THREE.Quaternion() };
  const corr = { Left: new THREE.Quaternion(), Right: new THREE.Quaternion() };
  // Bust spheres measured from her own bind-pose mesh, stored in Spine2 space so they move with the chest.
  const bust = [];
  (function measureBust() {
    const body = meshes.find((m) => m.isSkinnedMesh && /^Body_/.test(m.material.name)) || meshes.find((m) => m.isSkinnedMesh);
    const sp = bone.Spine2, foot = bone.LeftFoot, toe = bone.LeftToeBase;
    if (!body || !sp || !foot || !toe) return;
    root.updateMatrixWorld(true);
    const ji = body.skeleton.bones.indexOf(sp); if (ji < 0) return;
    const fwd = toe.getWorldPosition(new V()).sub(foot.getWorldPosition(new V())); fwd.y = 0; fwd.normalize();
    const up = new V(0, 1, 0), right = new V().crossVectors(fwd, up).normalize();
    const c0 = sp.getWorldPosition(new V());
    const pos = body.geometry.attributes.position, si = body.geometry.attributes.skinIndex, sw = body.geometry.attributes.skinWeight;
    const pts = []; const p = new V();
    for (let i = 0; i < pos.count; i++) {
      let w = 0; for (let k = 0; k < 4; k++) if (si.getComponent(i, k) === ji) w += sw.getComponent(i, k);
      if (w < 0.3) continue;
      body.getVertexPosition(i, p).applyMatrix4(body.matrixWorld);
      pts.push({ p: p.clone(), d: p.clone().sub(c0).dot(fwd) });
    }
    if (pts.length < 50) return;
    for (const s of [1, -1]) {
      const sideP = pts.filter((x) => x.p.clone().sub(c0).dot(right) * s > 0.03);
      const ds = sideP.map((x) => x.d).sort((a, b) => a - b); const cut = ds[Math.floor(ds.length * 0.8)];
      const sel = sideP.filter((x) => x.d >= cut);
      if (sel.length < 10) continue;
      const c = sel.reduce((a, x) => a.add(x.p), new V()).divideScalar(sel.length).addScaledVector(fwd, -0.045);
      bust.push({ local: sp.worldToLocal(c.clone()), r: 0.07 });
    }
  })();
  const colliders = (side) => {
    // radii in metres for this character (1.83 m with heels), measured from her mesh
    const other = side === 'Left' ? 'Right' : 'Left';
    const list = [
      { a: bone.Hips, b: bone.Spine1, r: 0.14 },
      { a: bone.Spine1, b: bone.Neck, r: 0.155 },
      { a: bone[other + 'Shoulder'], b: bone[other + 'Arm'], r: 0.06 },
      { a: bone.Neck, b: bone.Head, r: 0.06 },
      { a: bone[other + 'ForeArm'], b: bone[other + 'Hand'], r: 0.035, soft: 0.5 }, // forearms crossing
    ].filter((c) => c.a && c.b).map((c) => ({ A: c.a.getWorldPosition(new V()), B: c.b.getWorldPosition(new V()), r: c.r, soft: c.soft || 1 }));
    for (const b of bust) { const w = bone.Spine2.localToWorld(b.local.clone()); list.push({ A: w, B: w, r: b.r, soft: 1 }); }
    return list;
  };
  function closestOnSeg(p, a, b, out) {
    const ab = tmp.s.subVectors(b, a); const L2 = ab.lengthSq();
    const tt = L2 < 1e-9 ? 0 : Math.max(0, Math.min(1, tmp.c.subVectors(p, a).dot(ab) / L2));
    return out.copy(a).addScaledVector(ab, tt);
  }
  function solveArm(side, dt) {
    const upper = bone[side + 'Arm'], fore = bone[side + 'ForeArm'], hand = bone[side + 'Hand'];
    if (!upper || !fore || !hand) return;
    const shoulder = upper.getWorldPosition(new V());
    const E = fore.getWorldPosition(new V()), Hd = hand.getWorldPosition(new V());
    const mid = bone[side + 'HandMiddle1'];
    const pts = [Hd, E.clone().lerp(Hd, 0.33), E.clone().lerp(Hd, 0.66), E.clone().lerp(shoulder, 0.25)];
    if (mid) pts.push(mid.getWorldPosition(new V()));
    let best = 0; const push = new V(); let pt = null;
    for (const c of colliders(side)) {
      for (const p of pts) {
        const q = closestOnSeg(p, c.A, c.B, new V()); const d = p.distanceTo(q); const pen = (c.r + 0.025 - d) * c.soft; // 2.5 cm skin margin
        if (pen > best && d > 1e-5) { best = pen; push.subVectors(p, q).normalize(); pt = p; }
      }
    }
    const target = new THREE.Quaternion();
    if (pt && best > 0) {
      const lever = tmp.p.subVectors(pt, shoulder);
      tmp.axis.crossVectors(lever, push); const len = tmp.axis.length();
      if (len > 1e-5) { tmp.axis.divideScalar(len); target.setFromAxisAngle(tmp.axis, Math.min(0.6, best / lever.length()) * 1.15); }
    }
    corr[side].slerp(target, 1 - Math.exp(-dt * 18)); // smooth so it never pops
    // apply world-space correction to the upper arm
    upper.parent.getWorldQuaternion(tmp.pq);
    upper.getWorldQuaternion(tmp.wq);
    tmp.wq.premultiply(corr[side]);
    upper.quaternion.copy(tmp.pq.invert().multiply(tmp.wq));
    upper.updateMatrixWorld(true);
  }

  function update(dt) {
    t += dt;
    for (const e of eyeRig) e.b.quaternion.copy(e.rest); // clips without eye tracks would otherwise accumulate
    mixer.update(dt);
    root.updateMatrixWorld(true);
    if (o.antiClip) { solveArm('Left', dt); solveArm('Right', dt); }
    solveEyes(dt);
    if (bone.Head && o.hairSway) {
      const tip = bone.Head.localToWorld(tmp.p.set(0, -12, 4)); // a point at the hair ends, head space (cm)
      if (!hs.prev) hs.prev = tip.clone();
      const vel = tmp.c.subVectors(tip, hs.prev).divideScalar(Math.max(dt, 1e-3)); hs.prev.copy(tip);
      const target = tmp.s.copy(vel).multiplyScalar(-0.035 * o.hairSway); if (target.length() > 0.045) target.setLength(0.045);
      const acc = target.sub(hs.pos).multiplyScalar(90).addScaledVector(hs.vel, -11);
      hs.vel.addScaledVector(acc, dt); hs.pos.addScaledVector(hs.vel, dt);
      hairU.uHairSway.value.copy(hs.pos);
    }
    // CTBreath: weight = (P*cos(t*PI*f) + P) * 0.5  (Unity 0..100) -> three 0..1
    const w = ((o.breathPower * Math.cos(t * Math.PI * o.breathFrequency)) + o.breathPower) * 0.5 / 100 * state.breathScale;
    for (const m of breathTargets) m.morphTargetInfluences[m.morphTargetDictionary[o.breathMorph]] = w;
    let k = 0;
    if (o.blink) {
      if (t > nextBlink && blinkT < 0) blinkT = 0;
      if (blinkT >= 0) {
        blinkT += dt; k = blinkT < 0.08 ? blinkT / 0.08 : blinkT < 0.2 ? 1 - (blinkT - 0.08) / 0.12 : 0;
        if (blinkT > 0.2) { blinkT = -1; nextBlink = t + 2.5 + Math.random() * 4; }
      }
    }
    for (const m of pupilTargets) m.morphTargetInfluences[m.morphTargetDictionary.EyeSize] = o.pupil;
    const lid = o.lidRest + (1 - o.lidRest) * k;
    for (const m of blinkTargets) { const d = m.morphTargetDictionary; m.morphTargetInfluences[d.EyeLClose] = lid; m.morphTargetInfluences[d.EyeRClose] = lid; }
  }

  return { root, mixer, actions, addClip, play, setWeights, setOutfit, outfits, bone, update, state, options: o, skin: skinUniforms, hair: hairU, bust,
    get current() { return current; } };
}

// Rim-lit silhouette stage: strong coloured back lights, almost no front fill.
export function createSilhouetteRig(THREE, { color1 = 0x37d7ff, color2 = 0xff3cac, intensity = 120 } = {}) {
  const g = new THREE.Group(); g.name = 'DirroDancerRimRig';
  const mk = (c, x, y, z, i) => { const l = new THREE.SpotLight(c, i, 12, 0.45, 0.7, 2); l.position.set(x, y, z); l.target.position.set(0, 1.1, 0); g.add(l, l.target); return l; };
  const rimL = mk(color1, -1.6, 2.6, -2.2, intensity);
  const rimR = mk(color2, 1.6, 2.4, -2.2, intensity);
  const top = mk(0xffffff, 0, 4.2, -0.6, intensity * 0.25);
  const fill = new THREE.HemisphereLight(0x223355, 0x050208, 0.08); g.add(fill);
  return { group: g, rimL, rimR, top, fill };
}

// Handheld "GoPro" camera move around a target bone: slow orbit + layered shake.
export function handheldCamera(THREE, camera, targetObj, { distance = 0.7, height = 0.05, shake = 1 } = {}) {
  let t = Math.random() * 100; const p = new THREE.Vector3(), look = new THREE.Vector3();
  const n = (x) => Math.sin(x) * 0.6 + Math.sin(x * 2.3 + 1.7) * 0.3 + Math.sin(x * 5.1 + 0.4) * 0.1;
  return function step(dt) {
    t += dt; targetObj.getWorldPosition(look); look.y += height;
    const ang = Math.sin(t * 0.21) * 0.9;
    p.set(Math.sin(ang) * distance, n(t * 0.7) * 0.03 * shake, Math.cos(ang) * distance).add(look);
    camera.position.lerp(p, 1 - Math.exp(-dt * 3));
    look.x += n(t * 1.9) * 0.012 * shake; look.y += n(t * 2.3 + 4) * 0.012 * shake;
    camera.lookAt(look); camera.rotateZ(n(t * 1.3 + 9) * 0.02 * shake);
  };
}

// Soft key light that rides on the camera for close-ups (warm, wide penumbra, falls off with distance).
export function attachCameraKey(THREE, camera, { intensity = 3, color = 0xffe2cc } = {}) {
  const key = new THREE.SpotLight(color, intensity, 4, 0.55, 1.0, 2);
  key.position.set(0.25, 0.18, 0.05); key.target.position.set(0, -0.05, -1);
  camera.add(key, key.target); return key;
}
